# Change only DRIVE_PROJECT if you want a different storage folder, before first run.
# A hard runtime kill can leave a stale lock. Set True ONLY after terminating the old runtime.
DRIVE_PROJECT = "EXP012_ANOMALY_BENCHMARK_PREPARATION_V1"
RELEASE_STALE_LOCK = False
EXPECTED_BUNDLE_SHA256 = "8e034443158e5862eae83efa695f570294fe4f9a5f89791604e41b1f195e2c84"

import os,sys,json,hashlib,zipfile,time,subprocess,shutil,stat,platform
from pathlib import Path
from google.colab import drive,files

def file_sha(path):
    h=hashlib.sha256()
    with open(path,"rb") as f:
        for block in iter(lambda:f.read(1<<20),b""):h.update(block)
    return h.hexdigest()

drive.mount("/content/drive")
PROJECT=Path("/content/drive/MyDrive")/DRIVE_PROJECT
INPUTS=PROJECT/"inputs";OUTPUT=PROJECT/"results";LOGS=PROJECT/"logs"
for p in [INPUTS,OUTPUT,LOGS]:p.mkdir(parents=True,exist_ok=True)
BUNDLE=INPUTS/"EXP012_ANOMALY_BENCHMARK_PREPARATION_V1_input_bundle.zip"
SIDECAR=INPUTS/"EXP005_SELECTED_WEIGHTS_FOR_EXP012.zip"
if not BUNDLE.exists() or not SIDECAR.exists():
    print("Upload the EXP012 input bundle AND selected EXP005 sidecar in this one prompt.")
    uploaded=files.upload()
    for name,blob in uploaded.items():
        path=Path("/content")/Path(name).name
        path.write_bytes(blob)
        if file_sha(path)==EXPECTED_BUNDLE_SHA256:target=BUNDLE
        else:
            try:
                with zipfile.ZipFile(path) as z:m=json.loads(z.read("TRANSFER_MANIFEST.json"))
                if m.get("purpose")!="EXP012_SELECTED_EXP005_WEIGHTS":raise ValueError("Wrong sidecar purpose")
            except Exception as e:raise RuntimeError("Unrecognised input: "+name) from e
            target=SIDECAR
        if target.exists():
            if file_sha(target)!=file_sha(path):raise RuntimeError("Cached input differs; never overwrite an existing experiment input")
        else:
            tmp=target.with_suffix(".part");shutil.copyfile(path,tmp);os.replace(tmp,target)
    del uploaded
if not BUNDLE.exists() or not SIDECAR.exists():raise RuntimeError("Both inputs are required; no scientific fits started")
if file_sha(BUNDLE)!=EXPECTED_BUNDLE_SHA256:raise RuntimeError("Input bundle checksum mismatch")
with zipfile.ZipFile(SIDECAR) as z:
    m=json.loads(z.read("TRANSFER_MANIFEST.json"))
    if m.get("purpose")!="EXP012_SELECTED_EXP005_WEIGHTS" or len(m["files"])!=243:raise RuntimeError("Selected EXP005 inventory incomplete")
    if set(z.namelist())!=set(m["files"])|{"TRANSFER_MANIFEST.json"} or len(z.namelist())!=len(set(z.namelist())):raise RuntimeError("Unexpected/duplicate sidecar entry")
    for name,h in m["files"].items():
        if Path(name).name!=name or hashlib.sha256(z.read(name)).hexdigest()!=h:raise RuntimeError("Invalid sidecar checkpoint "+name)

WORK=Path("/content/EXP012_WORK");ROOT=WORK/"package";WORK.mkdir(exist_ok=True)
if ROOT.exists():shutil.rmtree(ROOT) # immutable input recreated; all results/progress live on Drive
ROOT.mkdir()
with zipfile.ZipFile(BUNDLE) as z:
    if len(z.namelist())!=len(set(z.namelist())):raise RuntimeError("Duplicate input ZIP paths")
    for item in z.infolist():
        dst=(ROOT/item.filename).resolve()
        if ROOT.resolve() not in dst.parents or stat.S_ISLNK(item.external_attr>>16):raise RuntimeError("Unsafe ZIP entry")
        if item.is_dir():dst.mkdir(parents=True,exist_ok=True);continue
        dst.parent.mkdir(parents=True,exist_ok=True);dst.write_bytes(z.read(item.filename))
manifest=json.loads((ROOT/"PACKAGE_MANIFEST.json").read_text())
actual={p.relative_to(ROOT).as_posix() for p in ROOT.rglob("*") if p.is_file() and p.name!="PACKAGE_MANIFEST.json"}
if actual!=set(manifest["files"]):raise RuntimeError("Input roster mismatch")
for name,h in manifest["files"].items():
    if file_sha(ROOT/name)!=h:raise RuntimeError("Input bytes changed: "+name)
print("Immutable TRAIN-only bundle and243 existing selected TCN weights verified.")
